import type { Localized } from './localized';

/** Responsive image generated by `npm run images`: `<src>-<width>.avif|webp` for each width. */
export interface ImageSource {
  /** Path without width suffix or extension, e.g. `/images/projects/medgate`. */
  readonly src: string;
  readonly widths: readonly number[];
  /** Intrinsic size of the largest variant (sets the aspect ratio before the image loads). */
  readonly width: number;
  readonly height: number;
}

export interface ProjectCover extends ImageSource {
  readonly alt: Localized;
}

export interface Project {
  readonly slug: string;
  /** Product name; proper nouns stay as written in both languages. */
  readonly title: string;
  readonly category: Localized;
  readonly summary: Localized;
  readonly stack: readonly string[];
  readonly tier: 'featured' | 'more';
  /** Real screenshot. When missing, the card shows a placeholder. */
  readonly cover?: ProjectCover;
}

export interface TitledText {
  readonly title: Localized;
  readonly text: Localized;
}

export interface ArchitectureLayer {
  readonly name: Localized;
  readonly note: Localized;
}

export interface Architecture {
  readonly intro: Localized;
  /** Top to bottom. */
  readonly layers: readonly ArchitectureLayer[];
  readonly reasons: readonly Localized[];
}

/**
 * Case-study content. Optional sections are simply not rendered when absent, so nothing has to
 * be invented: add `problem` / `outcomes` here once real facts are available.
 */
/** One screenshot in a case study's gallery. */
export interface GalleryItem extends ImageSource {
  readonly alt: Localized;
  readonly caption: Localized;
}

/** A tall page screenshot that scrolls inside a browser frame. */
export interface ScrollPreviewSource {
  readonly image: ImageSource;
  readonly alt: Localized;
  readonly caption: Localized;
}

/** Two states of the same screen, compared with a slider. */
export interface CompareSource {
  readonly before: ImageSource;
  readonly after: ImageSource;
  readonly beforeAlt: Localized;
  readonly afterAlt: Localized;
  readonly beforeLabel: Localized;
  readonly afterLabel: Localized;
  readonly caption: Localized;
}

export interface CaseStudy {
  readonly client?: Localized;
  readonly overview: Localized;
  readonly role: Localized;
  readonly problem?: Localized;
  readonly features: readonly Localized[];
  readonly architecture?: Architecture;
  readonly deepDive?: readonly TitledText[];
  readonly challenges?: readonly TitledText[];
  readonly testing?: Localized;
  readonly outcomes?: readonly Localized[];
  readonly gallery?: readonly GalleryItem[];
  /** Rendered only when real assets exist. */
  readonly scrollPreview?: ScrollPreviewSource;
  readonly compare?: CompareSource;
}

export interface CaseStudyEntry {
  readonly project: Project;
  readonly study: CaseStudy;
}
